#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — OpenReceipt private ChatGPT connection.
TOTAL_STAGES=4
TOTAL_MINUTES=15
umask 077
TASK_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
mkdir -p "$TASK_ROOT/bridge/data"
ENV_FILE="$TASK_ROOT/bridge/data/tunnel.env"
banner "Connect OpenReceipt to ChatGPT"
stage "Prepare your printer host" 5
say "First clone OpenReceipt on your 64-bit Linux host and start its Docker stack."
say "This prepares the official tunnel client, a scoped credential, and a wrapper."
ask OPENRECEIPT_PI_SSH "SSH destination for your printer host (user@hostname):"
[[ "$OPENRECEIPT_PI_SSH" =~ ^[A-Za-z0-9][A-Za-z0-9_.@:-]*$ ]] || { warn "Use an SSH hostname or user@hostname, without shell options."; exit 1; }
write_env OPENRECEIPT_PI_SSH "$OPENRECEIPT_PI_SSH"
SSH_CONTROL_DIR=$(mktemp -d /tmp/openreceipt-ssh.XXXXXX)
SSH_OPTIONS=(-o ControlMaster=auto -o ControlPersist=600 -o "ControlPath=$SSH_CONTROL_DIR/%C")
trap 'ssh "${SSH_OPTIONS[@]}" -O exit "$OPENRECEIPT_PI_SSH" >/dev/null 2>&1 || true; rm -rf "$SSH_CONTROL_DIR"' EXIT
REMOTE_HOME=$(ssh "${SSH_OPTIONS[@]}" "$OPENRECEIPT_PI_SSH" 'printf "%s" "$HOME"')
if ! _existing OPENRECEIPT_REMOTE_CHECKOUT >/dev/null; then write_env OPENRECEIPT_REMOTE_CHECKOUT "$REMOTE_HOME/openreceipt"; fi
ask OPENRECEIPT_REMOTE_CHECKOUT "Absolute OpenReceipt checkout path on the host:"
[[ "$OPENRECEIPT_REMOTE_CHECKOUT" == /* && "$OPENRECEIPT_REMOTE_CHECKOUT" != *$'\n'* ]] || { warn "Use an absolute path without newlines."; exit 1; }
write_env OPENRECEIPT_REMOTE_CHECKOUT "$OPENRECEIPT_REMOTE_CHECKOUT"
if ! _existing OPENRECEIPT_TUNNEL_DIR >/dev/null; then write_env OPENRECEIPT_TUNNEL_DIR "$REMOTE_HOME/.local/share/openreceipt/tunnel"; fi
ask OPENRECEIPT_TUNNEL_DIR "Absolute tunnel data directory on the host:"
[[ "$OPENRECEIPT_TUNNEL_DIR" == /* && "$OPENRECEIPT_TUNNEL_DIR" != *$'\n'* ]] || { warn "Use an absolute path without newlines."; exit 1; }
write_env OPENRECEIPT_TUNNEL_DIR "$OPENRECEIPT_TUNNEL_DIR"
run_remote() {
  local command
  printf -v command '%q ' "$@"
  ssh "${SSH_OPTIONS[@]}" "$OPENRECEIPT_PI_SSH" "$command"
}
AUTOMATIC=()
if confirm "Grant this ChatGPT credential automatic printing permission?"; then AUTOMATIC=(--automatic); fi
run_remote python3 "$OPENRECEIPT_REMOTE_CHECKOUT/scripts/setup-host.py" --checkout "$OPENRECEIPT_REMOTE_CHECKOUT" tunnel --directory "$OPENRECEIPT_TUNNEL_DIR" "${AUTOMATIC[@]}"
note "Review mode is the default. Automatic permission also needs your editor's autonomous policy."
stage "Create and link your tunnel" 4
open_url "https://platform.openai.com/settings/organization/tunnels"
step "Create a tunnel named OpenReceipt in your personal organization."
step "Associate it with the ChatGPT workspace/account where you will use the printer."
ask CONTROL_PLANE_TUNNEL_ID "Paste the tunnel ID (public, starts tunnel_):"
[[ "$CONTROL_PLANE_TUNNEL_ID" =~ ^tunnel_[A-Za-z0-9_-]+$ ]] || { warn "That isn't a tunnel ID."; exit 1; }
write_env CONTROL_PLANE_TUNNEL_ID "$CONTROL_PLANE_TUNNEL_ID"
stage "Save credentials and start the connection" 4
open_url "https://platform.openai.com/settings/organization/api-keys"
step "Create a runtime API key whose principal has Tunnels Read + Use."
note "Paste it here with hidden input. Don't paste it in chat."
ask_secret CONTROL_PLANE_API_KEY "Runtime API key:"
[[ "$CONTROL_PLANE_API_KEY" =~ ^sk-[A-Za-z0-9_-]+$ ]] || { warn "That isn't a runtime API key."; exit 1; }
write_env CONTROL_PLANE_API_KEY "$CONTROL_PLANE_API_KEY"
chmod 600 "$ENV_FILE"
printf '%s\n%s\n' "$CONTROL_PLANE_TUNNEL_ID" "$CONTROL_PLANE_API_KEY" | run_remote python3 "$OPENRECEIPT_REMOTE_CHECKOUT/scripts/setup-host.py" --checkout "$OPENRECEIPT_REMOTE_CHECKOUT" tunnel --directory "$OPENRECEIPT_TUNNEL_DIR" --save-account
printf -v ACTIVATE '%q ' python3 "$OPENRECEIPT_REMOTE_CHECKOUT/scripts/setup-host.py" --checkout "$OPENRECEIPT_REMOTE_CHECKOUT" tunnel --directory "$OPENRECEIPT_TUNNEL_DIR" --activate
say "Your host may ask for its sudo password in the SSH terminal."
ssh -t "${SSH_OPTIONS[@]}" "$OPENRECEIPT_PI_SSH" "$ACTIVATE"
stage "Connect in ChatGPT" 2
open_url "https://chatgpt.com/#settings/Connectors"
step "Add a custom MCP server, choose Tunnel, and select OpenReceipt (or enter its ID)."
step "Choose No authentication; the private tunnel wrapper already supplies the bridge credential."
step "Review the connection notice and create it as a plugin."
step "In a fresh chat, ask it to list your OpenReceipt receipts and preview one without printing."
pause "Press Enter after the preview appears."
finish
say "The printer host now owns the connection. Closing SSH does not stop it."
